create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('income','expense')),label text not null check(char_length(label) between 1 and 100),category text,amount numeric(18,2) not null check(amount>0),currency text not null default 'USD' check(currency in ('USD','CDF')),occurred_on date not null default current_date,created_at timestamptz not null default now());
create table if not exists public.transfers(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,recipient text not null,reference text,amount numeric(18,2) not null check(amount>0),currency text not null default 'USD' check(currency in ('USD','CDF')) ,transferred_on date not null default current_date,created_at timestamptz not null default now());
create index if not exists transactions_user_date_idx on public.transactions(user_id,occurred_on desc);create index if not exists transfers_user_date_idx on public.transfers(user_id,transferred_on desc);
alter table public.transactions enable row level security;alter table public.transfers enable row level security;
drop policy if exists tx_read_own on public.transactions;create policy tx_read_own on public.transactions for select to authenticated using((select auth.uid())=user_id);drop policy if exists tx_insert_own on public.transactions;create policy tx_insert_own on public.transactions for insert to authenticated with check((select auth.uid())=user_id);drop policy if exists tx_delete_own on public.transactions;create policy tx_delete_own on public.transactions for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists tr_read_own on public.transfers;create policy tr_read_own on public.transfers for select to authenticated using((select auth.uid())=user_id);drop policy if exists tr_insert_own on public.transfers;create policy tr_insert_own on public.transfers for insert to authenticated with check((select auth.uid())=user_id);drop policy if exists tr_delete_own on public.transfers;create policy tr_delete_own on public.transfers for delete to authenticated using((select auth.uid())=user_id);
grant usage on schema public to authenticated;grant select,insert,delete on public.transactions,public.transfers to authenticated;revoke all on public.transactions,public.transfers from anon;
alter table public.transactions add column if not exists currency text not null default 'USD';
alter table public.transfers add column if not exists currency text not null default 'USD';
alter table public.transactions drop constraint if exists transactions_currency_check;alter table public.transactions add constraint transactions_currency_check check(currency in ('USD','CDF'));
alter table public.transfers drop constraint if exists transfers_currency_check;alter table public.transfers add constraint transfers_currency_check check(currency in ('USD','CDF'));
